package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen1Test {

    private KeyedObjects2D dataset;
    private final Comparable col1 = "Col1";
    private final Comparable col2 = "Col2";
    private final Comparable row1 = "Row1";
    private final Comparable row2 = "Row2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKey_ThrowsException() {
        // Test branch: index < 1 (Unknown key)
        dataset.removeColumn("UnknownKey");
    }

    @Test
    public void testRemoveColumn_ValidKey_RemovesDataAndKey() {
        // Setup data
        dataset.addObject("Val1_1", row1, col1);
        dataset.addObject("Val1_2", row1, col2);
        dataset.addObject("Val2_1", row2, col1);
        dataset.addObject("Val2_2", row2, col2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Val1_1", dataset.getObject(row1, col1));

        // Execute
        dataset.removeColumn(col1);

        // Verify: Column key is removed from columnKeys list
        assertEquals(1, dataset.getColumnCount());
        assertFalse(dataset.getColumnKeys().contains(col1));
        assertTrue(dataset.getColumnKeys().contains(col2));

        // Verify: Data is removed from all rows
        // getObject with col1 should now return null or throw based on implementation, 
        // but according to the code, rowData.removeValue(i) is called.
        assertNull(dataset.getObject(row1, col1));
        assertNull(dataset.getObject(row2, col1));

        // Verify other data remains intact
        assertEquals("Val1_2", dataset.getObject(row1, col2));
        assertEquals("Val2_2", dataset.getObject(row2, col2));
    }

    @Test
    public void testRemoveColumn_KeyExistsButNoDataInRows() {
        // Setup a scenario where the column key exists in the dataset's column list,
        // but for some reason, the rows don't actually contain that column index (i < 0)
        // Although addObject usually ensures consistency, we test the branch logic: if (i >= 0)

        dataset.addObject("Val1_1", row1, col2);
        // We manually simulate a state if possible, but since we use public API:
        // We add col1 via a way that doesn't add row data if the implementation allowed it.
        // Since we can only use addObject, we'll ensure col1 is recognized but check coverage.

        // To trigger index >= 0 and i < 0 is difficult with just addObject.
        // However, the most important branches are the exception and the successful removal.
        dataset.removeColumn(col2);
        assertEquals(0, dataset.getColumnCount());
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Test removing a key that isn't there (already covered by exception test, 
        // but ensuring no crash on empty)
        try {
            dataset.removeColumn(col1);
        } catch (UnknownKeyException e) {
            // Expected
        }
        assertEquals(0, dataset.getColumnCount());
    }
}
